use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let year = input["input"][0].as_i64().unwrap();
    let month = input["input"][1].as_i64().unwrap();
    let day = input["input"][2].as_i64().unwrap();

    let mut days_in_month = [0; 12];
    days_in_month[0] = 31;
    days_in_month[1] = 28;
    days_in_month[2] = 31;
    days_in_month[3] = 30;
    days_in_month[4] = 31;
    days_in_month[5] = 30;
    days_in_month[6] = 31;
    days_in_month[7] = 31;
    days_in_month[8] = 30;
    days_in_month[9] = 31;
    days_in_month[10] = 30;
    days_in_month[11] = 31;

    if month == 2 {
        if (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0) {
            days_in_month[2] = 29;
        }
    }

    let mut day_of_year = 0;
    for i in 0..12 {
        day_of_year += days_in_month[i];
        if day_of_year > 365 {
            day_of_year -= 365;
            i += 1;
        }
    }

    day_of_year += day;

    serde_json::Value::Number(day_of_year)
}
